#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(void) {
    char s[1024];
    if (fgets(s, sizeof(s), stdin) == NULL) return 0;
    s[strcspn(s, "\n")] = 0;
    int count = 0;
    for (int i = 0; s[i]; i++) {
        if (isalpha((unsigned char)s[i])) count++;
    }
    printf("%d\n", count);
    return 0;
}

