#include <stdio.h>
#define PI 314
#define AREA_RECT(w, h) ((w) * (h))
#define AREA_CIRCLE(r) ((PI) * (r) * (r) / 100)

int main(void) {
    int shape;
    if (scanf("%d", &shape) != 1) return 0;
    if (shape == 1) {
        int w, h;
        if (scanf("%d %d", &w, &h) != 2) return 0;
        printf("%d\n", AREA_RECT(w, h));
    } else {
        int r;
        if (scanf("%d", &r) != 1) return 0;
        printf("%d\n", AREA_CIRCLE(r));
    }
    return 0;
}
